package com.zoro.zoromart.service;
import com.zoro.zoromart.dao.ProductDAO;import com.zoro.zoromart.util.ValidationUtil;import java.math.BigDecimal;import java.sql.SQLException;import java.util.List;import java.util.Map;
/** Validates product listing requests and delegates persistence to the DAO abstraction. */
public class ProductService {private final ProductDAO products;public ProductService(ProductDAO products){this.products=products;}public List<Map<String,Object>> search(String keyword,String category)throws SQLException{return products.search(keyword,category);}public long create(long sellerId,String name,String description,String priceText,int stock,String category,String imageUrl)throws SQLException{String validName=ValidationUtil.required(name,"name"),validDescription=ValidationUtil.required(description,"description"),validCategory=ValidationUtil.required(category,"category");BigDecimal price=ValidationUtil.price(priceText);if(stock<0)throw new IllegalArgumentException("Stock cannot be negative");return products.create(sellerId,validName,validDescription,price,stock,validCategory,validateImageUrl(imageUrl));}public boolean update(long id,long sellerId,String name,String description,String priceText,int stock,String category,String imageUrl)throws SQLException{String validName=ValidationUtil.required(name,"name"),validDescription=ValidationUtil.required(description,"description"),validCategory=ValidationUtil.required(category,"category");BigDecimal price=ValidationUtil.price(priceText);if(stock<0)throw new IllegalArgumentException("Stock cannot be negative");return products.update(id,sellerId,validName,validDescription,price,stock,validCategory,validateImageUrl(imageUrl));}public boolean delete(long id,long sellerId,boolean admin)throws SQLException{return products.delete(id,sellerId,admin);}public List<Map<String,Object>> ownListings(long sellerId)throws SQLException{return products.mine(sellerId);}private String validateImageUrl(String value){if(value==null||value.isBlank())return null;String v=value.trim();if(!(v.startsWith("https://")||v.startsWith("http://")))throw new IllegalArgumentException("Image URL must begin with http:// or https://");if(v.length()>1000)throw new IllegalArgumentException("Image URL is too long");return v;}}
